"""FROZEN reference: the pre-merge ``new_session`` / ``fetch_redirect_page``.

Generated mechanically from
``git show HEAD:services/protocol-payment/{ideal,twint,blik}/*.py`` before stage 1
(batch 10) moved both functions into ``common/session.py``. The two bodies were
AST-identical across the extractors apart from blik's one extra pre-proxy gate
(``IDEAL_USE_LOCAL_PROXY_ONLY``) and the ``*_FOLLOW_REDIRECT`` env-var name, so
two copies cover all three providers.

**Do not edit this file.** It is the "before" side of the differential test in
``tests/payment/test_session_batch10_parity.py``; editing it turns that test into
a comparison of the new code against itself.

The only transformation applied to the captured source is dependency injection:
every ambient name the body closed over is now an attribute of :class:`Seams`,
which the test fills from the extractor under test. No statement, literal or
expression was rewritten.
"""

from __future__ import annotations

from collections.abc import Callable
from typing import Any

import requests


def _required(value: Any, name: str) -> Any:
    """Fail loudly when a test forgets a seam instead of calling ``None``."""
    if value is None:
        raise AssertionError(f"stage1_batch10_head: seam {name!r} was not supplied")
    return value


class Seams:
    """The per-extractor values and callables the pre-merge bodies closed over."""

    def __init__(
        self,
        *,
        pre_proxy_url: Callable[..., str],
        register: Callable[[str], None],
        set_proxy: Callable[[Any, str], None],
        curl_session: Callable[..., Any] | None,
        curl_opt: Any = None,
        request_session: Callable[[], Any] = requests.Session,
        env_bool: Callable[..., bool] | None = None,
        dump_http: Callable[..., Any] | None = None,
        extract_qr_candidates: Callable[[str], list[str]] | None = None,
        follow_flag: str = "",
        timeout_default: float = 0.0,
        urljoin: Callable[[str, str], str] | None = None,
    ) -> None:
        self.pre_proxy_url = pre_proxy_url
        self.register = register
        self.set_proxy = set_proxy
        self.curl_session = curl_session
        self.curl_opt = curl_opt
        self.request_session = request_session
        self.env_bool = env_bool
        self.dump_http = dump_http
        self.extract_qr_candidates = extract_qr_candidates
        self.follow_flag = follow_flag
        self.timeout_default = timeout_default
        self.urljoin = urljoin


def new_session(proxy: str = "", use_pre_proxy: bool = True, *, seams: Seams) -> Any:
    """Pre-merge ``ideal`` / ``twint`` body."""
    pre_proxy = seams.pre_proxy_url() if use_pre_proxy else ""
    seams.register(pre_proxy)
    if seams.curl_session is not None:
        kwargs: dict[str, Any] = {"impersonate": "chrome136"}
        if pre_proxy:
            if seams.curl_opt is None:
                raise RuntimeError("本机前置代理需要 curl_cffi 支持")
            kwargs["curl_options"] = {seams.curl_opt.PRE_PROXY: pre_proxy}
        session = seams.curl_session(**kwargs)
    else:
        if pre_proxy:
            raise RuntimeError("本机前置代理需要 curl_cffi：python3 -m pip install curl_cffi")
        session = seams.request_session()
    if hasattr(session, "trust_env"):
        session.trust_env = False
    if proxy:
        seams.set_proxy(session, proxy)
    return session


def new_session_blik(proxy: str = "", use_pre_proxy: bool = True, *, seams: Seams) -> Any:
    """Pre-merge ``blik`` body: one extra gate on the pre-proxy line."""
    env_bool = _required(seams.env_bool, "env_bool")
    pre_proxy = (
        "" if env_bool("IDEAL_USE_LOCAL_PROXY_ONLY", False) else (seams.pre_proxy_url() if use_pre_proxy else "")
    )
    seams.register(pre_proxy)
    if seams.curl_session is not None:
        kwargs: dict[str, Any] = {"impersonate": "chrome136"}
        if pre_proxy:
            if seams.curl_opt is None:
                raise RuntimeError("本机前置代理需要 curl_cffi 支持")
            kwargs["curl_options"] = {seams.curl_opt.PRE_PROXY: pre_proxy}
        session = seams.curl_session(**kwargs)
    else:
        if pre_proxy:
            raise RuntimeError("本机前置代理需要 curl_cffi：python3 -m pip install curl_cffi")
        session = seams.request_session()
    if hasattr(session, "trust_env"):
        session.trust_env = False
    if proxy:
        seams.set_proxy(session, proxy)
    return session


def fetch_redirect_page(stripe: Any, start_url: str, *, seams: Seams) -> list[str]:
    """Pre-merge ``fetch_redirect_page`` body (identical in all three)."""
    env_bool = _required(seams.env_bool, "env_bool")
    dump_http = _required(seams.dump_http, "dump_http")
    extract_qr_candidates = _required(seams.extract_qr_candidates, "extract_qr_candidates")
    urljoin = _required(seams.urljoin, "urljoin")
    if not start_url or not env_bool(seams.follow_flag, True):
        return []
    current = start_url
    qr_urls: list[str] = []
    for hop in range(1, 6):
        resp = stripe.get(current, timeout=seams.timeout_default, allow_redirects=False)
        dump_http(resp, f"redirect_hop_{hop}", None, "GET", current, force=True)
        qr_urls.extend(extract_qr_candidates(resp.text))
        location = resp.headers.get("location") or resp.headers.get("Location") or ""
        if not location:
            break
        current = urljoin(current, location)
    return list(dict.fromkeys(qr_urls))
